{"type":"message","id":"f1af4328","parentId":"265e380a","timestamp":"2026-09-25T08:01:59.214Z","message":{"role":"toolResult","toolCallId":"call_zmO2lbMjX4CLTDi5fatmQULo|fc_08e9baa2f4f8fb1f016ab62a770c8887d090b29fb63ba03156","toolName":"read","content":[{"type":"text","text":"import { beforeEach, expect, test } from "bun:test";
import { add, clearDone, complete, count, get, isEmpty, list, reset } from "../src/store";

beforeEach(reset);

test("add then list returns the item", () => {
  add("a");
  expect(list()).toEqual([{ id: 1, title: "a", done: false, priority: "normal" }]);
});

test("add accepts an explicit priority", () => {
  expect(add("a", "high").priority).toBe("high");
});

test("add trims title edges and preserves interior whitespace", () => {
  const added = add(" \tpay  the\tbill \n ");
  expect(added.title).toBe("pay  the\tbill");
  expect(list()[0]?.title).toBe("pay  the\tbill");
});

test("add accepts a title that trims to empty", () => {
  const added = add(" \t ");
  expect(added.title).toBe("");
  expect(list()[0]?.title).toBe("");
});

test("complete marks the item done", () => {
  add("a");
  complete(1);
  expect(list({ done: true }).map((t) => t.id)).toEqual([1]);
});

test("open filter returns only undone items", () => {
  add("a");
  add("b");
  complete(1);
  expect(list({ done: false }).map((t) => t.id)).toEqual([2]);
});

test("high filter returns only high-priority items", () => {
  add("a", "high");
  add("b");
  expect(list({ priority: "high" }).map((t) => t.id)).toEqual([1]);
});

test("empty filter returns every item", () => {
  add("a");
  add("b");
  expect(list({}).map((t) => t.id)).toEqual([1, 2]);
});

test("isEmpty reports whether the store contains todos", () => {
  expect(isEmpty()).toBe(true);
  add("a");
  expect(isEmpty()).toBe(false);
});

test("count returns zero for an empty store", () => {
  expect(count()).toBe(0);
});

test("count includes completed todos in the total", () => {
  add("a");
  add("b");
  complete(1);
  expect(count()).toBe(2);
});

test("count applies a filter", () => {
  add("a", "high");
  add("b", "low");
  expect(count({ priority: "high" })).toBe(1);
});

test("count combines done and priority filters", () => {
  add("a", "low");
  add("b", "low");
  add("c", "high");
  complete(1);
  expect(count({ done: false, priority: "low" })).toBe(1);
});

test("count returns zero when no todos match", () => {
  add("a", "normal");
  expect(count({ priority: "high" })).toBe(0);
});

test("list filters by priority", () => {
  add("a", "high");
  add("b", "low");
  add("c", "high");
  expect(list({ priority: "high" }).map((t) => t.id)).toEqual([1, 3]);
});

test("list combines filter fields", () => {
  add("a", "low");
  add("b", "low");
  add("c", "high");
  complete(1);
  expect(list({ done: false, priority: "low" }).map((t) => t.id)).toEqual([2]);
});

test("list returns a new array", () => {
  add("a");
  list().pop();
  expect(list().length).toBe(1);
});

test("complete on a missing id returns false", () => {
  expect(complete(99)).toBe(false);
});

test("completing twice keeps the item done", () => {
  add("a");
  complete(1);
  complete(1);
  expect(list()).toEqual([{ id: 1, title: "a", done: true, priority: "normal" }]);
});

test("reset restarts ids at 1", () => {
  add("a");
  add("b");
  reset();
  expect(add("c").id).toBe(1);
});

test("get returns the item by id or undefined", () => {
  add("a");
  expect(get(1)?.title).toBe("a");
  expect(get(2)).toBeUndefined();
});

test("clearDone removes completed todos and preserves open todos", () => {
  const completedOne = add("completed one");
  const openOne = add("open one");
  const completedTwo = add("completed two");
  const openTwo = add("open two");
  complete(completedOne.id);
  complete(completedTwo.id);
  const priorSnapshot = list();

  expect(clearDone()).toBe(2);

  const survivors = list();
  expect(survivors).toEqual([
    { id: 2, title: "open one", done: false, priority: "normal" },
    { id: 4, title: "open two", done: false, priority: "normal" },
  ]);
  expect(survivors[0]).toBe(openOne);
  expect(survivors[1]).toBe(openTwo);
  expect(priorSnapshot.map((todo) => todo.id)).toEqual([1, 2, 3, 4]);
  expect(count()).toBe(2);
  expect(clearDone()).toBe(0);
  expect(add("after clear").id).toBe(5);
});

test("clearDone returns zero when there are no completed todos", () => {
  expect(clearDone()).toBe(0);
  expect(list()).toEqual([]);
  expect(count()).toBe(0);

  const openTodo = add("open");
  expect(clearDone()).toBe(0);
  expect(list()).toEqual([
    { id: 1, title: "open", done: false, priority: "normal" },
  ]);
  expect(list()[0]).toBe(openTodo);
});
