    out: '{"id":1,"title":"buy milk","done":false,"priority":"high"}',
  });
});

test("add defaults to normal priority", () => {
  expect(run("add", "buy", "milk")).toMatchObject({
    code: 0,
    out: '{"id":1,"title":"buy milk","done":false,"priority":"normal"}',
  });
});

test("list open", () => {
  expect(run("list", "open")).toMatchObject({ code: 0, out: "[]" });
});

test("count returns zero in a fresh process", () => {
  expect(run("count")).toMatchObject({ code: 0, out: "0" });
});

test("empty returns true in a fresh process", () => {
  expect(run("empty")).toMatchObject({ code: 0, out: "true", err: "" });
});

test("count accepts a supported filter", () => {
  expect(run("count", "high")).toMatchObject({ code: 0, out: "0" });
});

test("count with an unknown filter reports the existing filter error", () => {
  const r = run("count", "hgih");
  expect(r.code).toBe(1);
  expect(r.err).toContain('unknown filter "hgih" (expected open, done, low, normal, high)');
});

test("count starts empty after an add in another process", () => {
  expect(run("add", "buy", "milk").code).toBe(0);
  expect(run("count")).toMatchObject({ code: 0, out: "0" });
});

test("list with unknown filter", () => {
  const r = run("list", "hgih");
  expect(r.code).toBe(1);
  expect(r.err).toContain('unknown filter "hgih" (expected open, done, low, normal, high)');
});

test("add with unknown priority", () => {
  expect(run("add", "-p", "urgent", "x").code).toBe(1);
});

test("add with missing priority", () => {
  const r = run("add", "-p");
  expect(r.code).toBe(1);
  expect(r.err).toBe("error: missing priority after -p (expected low, normal, high)\n");
});

test("unknown command", () => {
  expect(run("frob").code).toBe(1);
});
