import { type Filter, PRIORITIES, type Priority } from "./model";
import { add, clearDone, complete, count, isEmpty, list } from "./store";

const FILTERS = new Map<string, Filter>([
  ["open", { done: false }],
  ["done", { done: true }],
  ...PRIORITIES.map((p) => [p, { priority: p }] as const),
]);

function parseFilter(token: string | undefined): Filter {
  if (token === undefined) return {};
  const f = FILTERS.get(token);
  if (!f) throw new Error(`unknown filter "${token}" (expected ${[...FILTERS.keys()].join(", ")})`);
  return f;
}

function parsePriority(s: string): Priority {
  const p = PRIORITIES.find((x) => x === s);
  if (!p) throw new Error(`unknown priority "${s}" (expected ${PRIORITIES.join(", ")})`);
  return p;
}

function parseAdd(args: string[]): [string, Priority] {
  let priority: Priority = "normal";
  if (args[0] === "-p") {
    if (args[1] === undefined) throw new Error(`missing priority after -p (expected ${PRIORITIES.join(", ")})`);
    priority = parsePriority(args[1]);
    args = args.slice(2);
  }
  const title = args.join(" ");
  if (!title) throw new Error("empty title");
  return [title, priority];
}

try {
  const [cmd, ...rest] = process.argv.slice(2);
  if (cmd === "add") console.log(JSON.stringify(add(...parseAdd(rest))));
  else if (cmd === "done") console.log(complete(Number(rest[0])));
  else if (cmd === "clear-done") console.log(clearDone());
  else if (cmd === "list") console.log(JSON.stringify(list(parseFilter(rest[0]))));
  else if (cmd === "count") console.log(count(parseFilter(rest[0])));
  else if (cmd === "empty") console.log(isEmpty());
  else if (cmd === undefined) console.log(JSON.stringify(list()));
  else throw new Error(`unknown command "${cmd}"`);
} catch (e) {
  console.error(`error: ${e instanceof Error ? e.message : String(e)}`);
  process.exit(1);
}

import { filterTodos } from "./filters";
import type { Filter, Priority, Todo } from "./model";

let nextId = 1;
let todos: Todo[] = [];

export function add(title: string, priority: Priority = "normal"): Todo {
  const t = { id: nextId++, title: title.trim(), done: false, priority };
  todos.push(t);
  return t;
}

export function complete(id: number): boolean {
  const t = todos.find((x) => x.id == id);
  if (!t) return false;
  t.done = true;
  return true;
}

export function clearDone(): number {
  const previousLength = todos.length;
  todos = todos.filter((todo) => !todo.done);
  return previousLength - todos.length;
}

export function isEmpty(): boolean {
  return todos.length === 0;
}

export function list(filter: Filter = {}): Todo[] {
  return filterTodos(todos, filter);
}

export function count(filter: Filter = {}): number { return list(filter).length; }

export function get(id: number): Todo | undefined {
  return todos.find((x) => x.id === id);
}

export function reset(): void {
  todos.length = 0;
  nextId = 1;
}

export const PRIORITIES = ["low", "normal", "high"] as const;
export type Priority = (typeof PRIORITIES)[number];
export type Todo = { id: number; title: string; done: boolean; priority: Priority };
export type Filter = Partial<Pick<Todo, "done" | "priority">>;

import type { Filter, Todo } from "./model";

export function filterTodos(todos: Todo[], filter: Filter = {}): Todo[] {
  return todos.filter(
    (t) =>
      (filter.done === undefined || t.done === filter.done) &&
      (filter.priority === undefined || t.priority === filter.priority),
  );
}

import { beforeEach, expect, test } from "bun:test";
import { add, clearDone, complete, count, get, isEmpty, list, reset } from "../src/store";

beforeEach(reset);

test("add then list returns the item", () => {
  add("a");
  expect(list()).toEqual([{ id: 1, title: "a", done: false, priority: "normal" }]);
});

test("add accepts an explicit priority", () => {
  expect(add("a", "high").priority).toBe("high");
});

test("add trims title edges and preserves interior whitespace", () => {
  const added = add(" \tpay  the\tbill \n ");
  expect(added.title).toBe("pay  the\tbill");
  expect(list()[0]?.title).toBe("pay  the\tbill");
});

test("add accepts a title that trims to empty", () => {
  const added = add(" \t ");
  expect(added.title).toBe("");
  expect(list()[0]?.title).toBe("");
});

test("complete marks the item done", () => {
  add("a");
  complete(1);
  expect(list({ done: true }).map((t) => t.id)).toEqual([1]);
});

test("open filter returns only undone items", () => {
  add("a");
  add("b");
  complete(1);
  expect(list({ done: false }).map((t) => t.id)).toEqual([2]);
});

test("high filter returns only high-priority items", () => {
  add("a", "high");
  add("b");
  expect(list({ priority: "high" }).map((t) => t.id)).toEqual([1]);
});

test("empty filter returns every item", () => {
  add("a");
  add("b");
  expect(list({}).map((t) => t.id)).toEqual([1, 2]);
});

test("isEmpty reports whether the store contains todos", () => {
  expect(isEmpty()).toBe(true);
  add("a");
  expect(isEmpty()).toBe(false);
});

test("count returns zero for an empty store", () => {
  expect(count()).toBe(0);
});

test("count includes completed todos in the total", () => {
  add("a");
  add("b");
  complete(1);
  expect(count()).toBe(2);
});

test("count applies a filter", () => {
  add("a", "high");
  add("b", "low");
  expect(count({ priority: "high" })).toBe(1);
});

test("count combines done and priority filters", () => {
  add("a", "low");
  add("b", "low");
  add("c", "high");
  complete(1);
  expect(count({ done: false, priority: "low" })).toBe(1);
});

test("count returns zero when no todos match", () => {
  add("a", "normal");
  expect(count({ priority: "high" })).toBe(0);
});

test("list filters by priority", () => {
  add("a", "high");
  add("b", "low");
  add("c", "high");
  expect(list({ priority: "high" }).map((t) => t.id)).toEqual([1, 3]);
});

test("list combines filter fields", () => {
  add("a", "low");
  add("b", "low");
  add("c", "high");
  complete(1);
  expect(list({ done: false, priority: "low" }).map((t) => t.id)).toEqual([2]);
});

test("list returns a new array", () => {
  add("a");
  list().pop();
  expect(list().length).toBe(1);
});

test("complete on a missing id returns false", () => {
  expect(complete(99)).toBe(false);
});

test("completing twice keeps the item done", () => {
  add("a");
  complete(1);
  complete(1);
  expect(list()).toEqual([{ id: 1, title: "a", done: true, priority: "normal" }]);
});

test("reset restarts ids at 1", () => {
  add("a");
  add("b");
  reset();
  expect(add("c").id).toBe(1);
});

test("get returns the item by id or undefined", () => {
  add("a");
  expect(get(1)?.title).toBe("a");
  expect(get(2)).toBeUndefined();
});

test("clearDone removes completed todos and preserves open todos", () => {
  const completedOne = add("completed one");
  const openOne = add("open one");
  const completedTwo = add("completed two");
  const openTwo = add("open two");
  complete(completedOne.id);
  complete(completedTwo.id);
  const priorSnapshot = list();

  expect(clearDone()).toBe(2);

  const survivors = list();
  expect(survivors).toEqual([
    { id: 2, title: "open one", done: false, priority: "normal" },
    { id: 4, title: "open two", done: false, priority: "normal" },
  ]);
  expect(survivors[0]).toBe(openOne);
  expect(survivors[1]).toBe(openTwo);
  expect(priorSnapshot.map((todo) => todo.id)).toEqual([1, 2, 3, 4]);
  expect(count()).toBe(2);
  expect(clearDone()).toBe(0);
  expect(add("after clear").id).toBe(5);
});

test("clearDone returns zero when there are no completed todos", () => {
  expect(clearDone()).toBe(0);
  expect(list()).toEqual([]);
  expect(count()).toBe(0);

  const openTodo = add("open");
  expect(clearDone()).toBe(0);
  expect(list()).toEqual([
    { id: 1, title: "open", done: false, priority: "normal" },
  ]);
  expect(list()[0]).toBe(openTodo);
});

