import { type Filter, PRIORITIES, type Priority } from "./model";
import { add, clearDone, complete, count, isEmpty, list, rename } from "./store";

const FILTERS = new Map<string, Filter>([
  ["open", { done: false }],
  ["done", { done: true }],
  ...PRIORITIES.map((p) => [p, { priority: p }] as const),
]);

function parseFilter(token: string | undefined): Filter {
  if (token === undefined) return {};
  const f = FILTERS.get(token);
  if (!f) throw new Error(`unknown filter "${token}" (expected ${[...FILTERS.keys()].join(", ")})`);
  return f;
}

function parsePriority(s: string): Priority {
  const p = PRIORITIES.find((x) => x === s);
  if (!p) throw new Error(`unknown priority "${s}" (expected ${PRIORITIES.join(", ")})`);
  return p;
}

function parseAdd(args: string[]): [string, Priority] {
  let priority: Priority = "normal";
  if (args[0] === "-p") {
    if (args[1] === undefined) throw new Error(`missing priority after -p (expected ${PRIORITIES.join(", ")})`);
    priority = parsePriority(args[1]);
    args = args.slice(2);
  }
  const title = args.join(" ");
  if (!title) throw new Error("empty title");
  return [title, priority];
}

try {
  const [cmd, ...rest] = process.argv.slice(2);
  if (cmd === "add") console.log(JSON.stringify(add(...parseAdd(rest))));
  else if (cmd === "done") console.log(complete(Number(rest[0])));
  else if (cmd === "clear-done") console.log(clearDone());
  else if (cmd === "rename") {
    const title = rest.slice(1).join(" ");
    if (!title) throw new Error("missing title");
    console.log(rename(Number(rest[0]), title));
  }
  else if (cmd === "list") console.log(JSON.stringify(list(parseFilter(rest[0]))));
  else if (cmd === "count") console.log(count(parseFilter(rest[0])));
  else if (cmd === "empty") console.log(isEmpty());
  else if (cmd === undefined) console.log(JSON.stringify(list()));
  else throw new Error(`unknown command "${cmd}"`);
} catch (e) {
  console.error(`error: ${e instanceof Error ? e.message : String(e)}`);
  process.exit(1);
}

test("add with unknown priority", () => {
  expect(run("add", "-p", "urgent", "x").code).toBe(1);
});

test("add with missing priority", () => {
  const r = run("add", "-p");
  expect(r.code).toBe(1);
  expect(r.err).toBe("error: missing priority after -p (expected low, normal, high)\n");
});

test("unknown command", () => {
  expect(run("frob").code).toBe(1);
});

test("clear-done removes completed todos and keeps open todos", () => {
  const r = Bun.spawnSync([
    "bun",
    "-e",
    `
      const { add, complete, list } = await import("./src/store.ts");
      const done = add("remove me");
      add("keep me");
      complete(done.id);
      process.argv = ["bun", "src/cli.ts", "clear-done"];
      await import("./src/cli.ts");
      console.log(JSON.stringify(list()));
    `,
  ]);

  expect(r.exitCode).toBe(0);
  expect(r.stdout.toString()).toBe('1\n[{"id":2,"title":"keep me","done":false,"priority":"normal"}]\n');
  expect(r.stderr.toString()).toBe("");
});

function runWithSeededTodo(...args: string[]) {
  const script = `
    import { add, list } from "./src/store.ts";
    add("old title");
    process.argv = ["bun", "src/cli.ts", ...${JSON.stringify(args)}];
    await import("./src/cli.ts");
    console.log(JSON.stringify(list()));
  `;
  const r = Bun.spawnSync(["bun", "-e", script]);
  return { code: r.exitCode, out: r.stdout.toString().trim(), err: r.stderr.toString() };
}

test("rename updates the selected todo title", () => {
  expect(runWithSeededTodo("rename", "1", "new", "title")).toEqual({
    code: 0,
    out: 'true\n[{"id":1,"title":"new title","done":false,"priority":"normal"}]',
    err: "",
  });
});

test("rename returns false when the id does not exist", () => {
  expect(runWithSeededTodo("rename", "99", "new title")).toEqual({
    code: 0,
    out: 'false\n[{"id":1,"title":"old title","done":false,"priority":"normal"}]',
    err: "",
  });
});

test("rename reports a missing title", () => {
  const result = runWithSeededTodo("rename", "1");
  expect(result.code).toBe(1);
  expect(result.err).toBe("error: missing title\n");
});

import { filterTodos } from "./filters";
import type { Filter, Priority, Todo } from "./model";

let nextId = 1;
let todos: Todo[] = [];

export function add(title: string, priority: Priority = "normal"): Todo {
  const t = { id: nextId++, title: title.trim(), done: false, priority };
  todos.push(t);
  return t;
}

export function complete(id: number): boolean {
  const t = todos.find((x) => x.id == id);
  if (!t) return false;
  t.done = true;
  return true;
}

export function rename(id: number, title: string): boolean {
  const t = todos.find((x) => x.id === id);
  if (!t) return false;
  t.title = title.trim();
  return true;
}

export function clearDone(): number {
  const previousLength = todos.length;
  todos = todos.filter((todo) => !todo.done);
  return previousLength - todos.length;
}

export function isEmpty(): boolean {
  return todos.length === 0;
}

export function list(filter: Filter = {}): Todo[] {
  return filterTodos(todos, filter);
}

export function count(filter: Filter = {}): number { return list(filter).length; }

export function get(id: number): Todo | undefined {
  return todos.find((x) => x.id === id);
}

export function reset(): void {
  todos.length = 0;
  nextId = 1;
}

